package com.gameaggregator.tenantservice.api; import jakarta.validation.constraints.*; import java.util.*; public final class TenantDtos { private TenantDtos(){} public record CreateTenant(@NotBlank @Pattern(regexp="[a-z0-9-]{3,120}") String slug,@NotBlank @Size(max=200) String name){} public record CreateOrganization(@NotBlank String slug,@NotBlank String name,@NotBlank String type){} public record AddMember(@NotNull UUID userId){} public record CreateRole(@NotBlank String code,@NotBlank String name,Set<String> permissions){} public record TenantView(UUID id,String slug,String name,String status){} public record OrganizationView(UUID id,UUID tenantId,String slug,String name,String type){} public record MemberView(UUID id,UUID tenantId,UUID userId,String status){} public record RoleView(UUID id,String code,String name,Set<String> permissions){} public record AccessContext(UUID currentUserId,UUID currentTenantId,Set<String> currentRoles,Set<String> currentPermissions){} }
